<template>
  <fieldset>
    <legend>Association</legend>
    <table class="editorTable">
      <tr>
        <td
          >Label on target
          <InfoButton>
            <p> This is the label that may appear on the target item when listing associated items. </p>
            Examples:
            <ul>
              <li>for a "Leader" association, this could be "Leading"</li>
              <li>for a "Owned by" association, this could be "Granted Items"</li>
              <li>for a "Regiment" association, this could be "Units"</li>
            </ul> </InfoButton
          >:</td
        >
        <td><input type="text" v-model="item.label" /> </td>
      </tr>
      <tr>
        <td>Min</td>
        <td><input @input="changed" v-model="item.min" type="number" /></td>
      </tr>
      <tr>
        <td>Max</td>
        <td><input @input="changed" v-model="item.max" type="number" /></td>
      </tr>
      <tr>
        <td>Default Selection</td>
        <td>
          <UtilAutocomplete
            v-model="item.defaultSelectionEntryId"
            :placeholder="`Search Children...`"
            :options="[
              {
                name: 'Auto',
                id: undefined,
                editorTypeName: 'bullet',
              },
              {
                name: 'None',
                id: 'none',
                editorTypeName: 'bullet',
              },
            ]"
            valueField="id"
            filterField="name"
          >
            <template #option="opt">
              <div style="white-space: nowrap">
                <template v-if="opt.option.indent >= 2 && !opt.selected"
                  ><span v-for="n of opt.option.indent - 1">&nbsp;&nbsp;&nbsp;</span></template
                >
                <img class="mr-1 align-middle" :src="`assets/bsicons/${opt.option.editorTypeName}.png`" />
                {{ opt.option.name }}
              </div>
            </template>
          </UtilAutocomplete>
        </td>
      </tr>
      <tr>
        <td>Ids</td>
        <td></td>
      </tr>
      <tr>
        <td>Action (Not implemented yet)</td>
        <td>
          <select v-model="item.action">
            <option :value="undefined">Not defined</option>
            <option value="append">Append</option>
            <option value="replace">Replace</option>
            <option value="overwrite">Overwrite</option>
            <option value="group">Group</option>
          </select>
        </td>
      </tr>
      <tr>
        <td>Splitting behavior (Not implemented yet)</td>
        <td>
          <select v-model="item.splittingBehavior">
            <option :value="undefined">Not defined</option>
            <option value="combine">Combine</option>
            <option value="split">Split</option>
          </select>
        </td>
      </tr>
    </table>
  </fieldset>
</template>

<script lang="ts">
import type { PropType } from "vue";
import type { EditorBase } from "~/assets/shared/battlescribe/bs_main_catalogue";
import type { NRAssociation } from "~/assets/shared/battlescribe/bs_types";
import InfoButton from "~/components/InfoButton.vue";
import { useEditorStore } from "~/stores/editorStore";

export default {
  setup() {
    return { store: useEditorStore() };
  },
  methods: {
    /**
     * Marks the catalogue unsaved. These edits deliberately bypass store.set_field -- the id
     * has to move the node in the index, min/max are raw v-model, categories mutate a links
     * array -- and set_field is what otherwise reports the change, so without this the edit
     * lands but the save indicator never lights up. Was calling a `changed()` that no
     * component defined, so it threw instead.
     */
    changed() {
      this.store.changed(this.item as EditorBase);
    },
  },
  props: {
    item: {
      type: Object as PropType<NRAssociation & EditorBase>,
      required: true,
    },
  },
};
</script>
