<template>
  <fieldset>
    <legend>Filter By</legend>
    <table class="editorTable">
      <tr>
        <td>Child ID:</td>
        <td><input type="text" v-model="childId" /> </td
      ></tr>

      <tr>
        <td>Child:</td>
        <td>
          <UtilAutocomplete
            v-model="childId"
            :placeholder="`Search Child...`"
            :options="availableTargets"
            valueField="id"
            filterField="name"
            :default="child"
            lazy
          >
            <template #option="opt">
              <div v-if="opt.option" style="white-space: nowrap">
                <template v-if="opt.option.indent >= 1 && !opt.selected">
                  <span v-for="n of opt.option.indent">&nbsp;&nbsp;&nbsp;</span>
                </template>
                <img class="mr-1 align-middle" :src="`assets/bsicons/${opt.option.editorTypeName}.png`" />

                {{ opt.option.name }}
                <span class="gray">{{ getNameExtra(opt.option, false) }}</span>
                <span class="shared" v-if="opt.option.shared"> (shared) </span>
                <span class="gray" v-if="opt.option.rootId === rootId"> (same ancestor)</span>
                <span class="catalogueName" v-if="showCatalogue(opt.option)"> [{{ opt.option.catalogue }}]</span>
              </div>
            </template>
          </UtilAutocomplete>
        </td>
      </tr>
    </table>
    <span v-if="!hideshared">
      <input :disabled="noshared && item.shared" type="checkbox" v-model="item.shared" id="shared" />
      <label
        :class="{ gray: noshared && item.shared }"
        class="hastooltip"
        :title="`Its recommended to keep shared checked on ${item.editorTypeName}s`"
        for="shared"
        >Shared?</label
      >
    </span>
  </fieldset>
</template>

<script lang="ts">
import type { QueryNode } from "./props";
import { Catalogue } from "~/assets/shared/battlescribe/bs_main_catalogue";
import type { BSICondition } from "~/assets/shared/battlescribe/bs_types";
import type { EditorBase } from "~/assets/shared/battlescribe/bs_main_catalogue";

import {
  getSearchElements,
  getSearchCategories,
  getFilterSelections,
  getSearchSelections,
  getSearchCatalogues,
  scopeIsId,
} from "@/assets/ts/catalogue/catalogue_helpers";
import type { EditorSearchItem } from "@/assets/ts/catalogue/catalogue_helpers";
import { getNameExtra } from "~/assets/editor/bs_editor";
import { filterByItems } from "~/assets/editor/bs_editor";
import { fieldToText } from "~/assets/shared/battlescribe/bs_modifiers";
import { Base, Condition, Constraint } from "~/assets/shared/battlescribe/bs_main";
export default {
  props: {
    item: {
      type: Object as PropType<QueryNode>,
      required: true,
    },

    catalogue: {
      type: Object as PropType<Catalogue>,
      required: true,
    },

    hideshared: {
      type: Boolean,
      default: false,
    },
    noshared: {
      type: Boolean,
      default: false,
    },
  },

  methods: {
    getNameExtra,
    showCatalogue(opt: EditorSearchItem): boolean {
      if (!opt.catalogue) {
        return false;
      }
      if (opt.catalogue === this.item.catalogue?.getName()) {
        return false;
      }
      return true;
    },
    availableTargets() {
      // Runtime aliases both types to this filter id (see getStaticFilters); association filters only
      const modelOrUnit = this.inAssociation
        ? [{ id: "model-or-unit", name: "Model or Unit", editorTypeName: "bullet", indent: 0, catalogue: null, shared: false }]
        : [];
      const result = [
        ...filterByItems,
        ...modelOrUnit,
        ...this.allCategories,
        ...this.allEntries,
        ...this.allForces,
        ...this.allCatalogues,
        ...this.allAssociations
      ];
      return result;
    },
  },

  watch: {
    "item.scope"() {
      if (!this.child) {
        (this.item as Partial<typeof this.item>).childId = this.availableTargets()[0]?.id || undefined;
      }
    },
  },

  computed: {
    childId: {
      get() {
        return this.item.childId;
      },
      set(id: string) {
        const old = this.item.childId;
        this.item.childId = id;
        this.item.childName = fieldToText(this.item, id);
        this.catalogue.updateCondition(this.item, old);
      },
    },
    child() {
      if (!this.item.childId) {
        return null;
      }

      const base = this.availableTargets().find((elt) => elt.id === this.item.childId);
      if (base) {
        return base;
      }
      return this.catalogue.findOptionById(this.item.childId) as any as EditorSearchItem;
    },

    instanceOf() {
      return ["instanceOf", "notInstanceOf"].includes(this.item?.type ?? "");
    },

    allEntries(): EditorSearchItem[] {
      if (!this.includeSelections) {
        return [];
      }

      // Conditions/constraints nested under an association evaluate against the
      // associated node, which can be any entry in the catalogue, so offer all
      // root selection entries instead of only those reachable from the scope.
      if (this.inAssociation) {
        return getSearchSelections(this.catalogue, true);
      }

      return getFilterSelections(this.item, this.catalogue);
    },

    inAssociation(): boolean {
      let parent: EditorBase | undefined = this.item as EditorBase;
      while (parent) {
        if (typeof parent.parentKey === "string" && parent.parentKey.toLowerCase().includes("association")) {
          return true;
        }
        parent = parent.parent;
      }
      return false;
    },

    rootId() {
      let item = this.item as any;
      if (!item?.parent) return;
      while (item?.parent && !item.parent.isCatalogue()) {
        item = item.parent;
      }
      return item.id;
    },
    allCategories(): EditorSearchItem[] {
      if (!this.includeCategories) {
        return [];
      }
      return getSearchCategories(this.catalogue);
    },

    allForces(): EditorSearchItem[] {
      if (!this.includeForces) {
        return [];
      }
      return getSearchElements(this.catalogue, "forceEntriesIterator");
    },
    allAssociations(): EditorSearchItem[] {
      if (!this.includeSelections) {
        return [];
      }
      return getSearchElements(this.catalogue, "associationsIterator");

    },
    allCatalogues(): EditorSearchItem[] {
      if (!this.includeCatalogues) {
        return [];
      }
      return getSearchCatalogues(this.catalogue);
    },
    includeAssociatiosn(){
      if (this.item.field !== "associations") {
        return false;
      }
      return true;
    },
    includeSelections() {
      if (this.instanceOf && this.item.scope === "primary-catalogue") {
        return false;
      }
      if (this.instanceOf && this.item.scope === "primary-category") {
        return false;
      }

      return true;
    },

    includeCategories() {
      if (this.instanceOf && this.item.scope === "primary-catalogue") {
        return false;
      }

      if (this.item.field === "forces") {
        return false;
      }
      return true;
    },

    includeForces() {
      if (this.item.scope == "self") {
        return false;
      }
      if (this.item.scope == "parent") {
        return false;
      }
      if (this.item.scope == "ancestor") {
        return true;
      }
      if (this.item.field === "associations") {
        return false;
      }
      if (this.instanceOf && this.item.scope === "primary-catalogue") {
        return false;
      }
      if (this.instanceOf && this.item.scope === "primary-category") {
        return false;
      }

      if (scopeIsId(this.item)) {
        return false;
      }

      return true;
    },

    includeCatalogues() {
      return this.instanceOf && this.item.scope === "primary-catalogue";
    },
  },
};
</script>

<style scoped lang="scss">
@use "@/shared_components/css/vars.scss" as *;

.catalogueName {
  color: rgb(144, 152, 197);
  font-style: italic;
}

.shared {
  color: $gray;
  font-style: italic;
}
</style>
