<template>
  <fieldset>
    <legend>Query</legend>
    <table class="editorTable">
      <tr>
        <td>Scope:</td>
        <td>
          <UtilAutocomplete
            v-model="scopeBase"
            placeholder="Search Scope..."
            :options="allScopes"
            valueField="id"
            filterField="name"
            :default="allScopes[0]"
          >
            <template #option="opt">
              <div style="white-space: nowrap">
                <template v-if="opt.option.indent >= 2 && !opt.selected">
                  <span v-for="n of opt.option.indent - 1">&nbsp;&nbsp;&nbsp;</span>
                </template>
                <img class="mr-1 align-middle" :src="`assets/bsicons/${opt.option.editorTypeName || 'bullet'}.png`" />
                {{ opt.option.name }}
                <span class="gray">{{ getNameExtra(opt.option, false) }}</span>
                <span class="shared" v-if="opt.option.shared"> (shared)</span>
                <span class="catalogueName" v-if="showCatalogue(opt.option)"> [{{ opt.option.catalogue }}]</span>
              </div>
            </template>
          </UtilAutocomplete>
        </td>
      </tr>
      <tr>
        <td>Affects: </td>
        <td>
          <UtilAutocomplete
            v-model="fields.affectsWhat"
            placeholder="Entries"
            :options="allAffects"
            valueField="value"
            :filterField="(option) => option.prefix ? `${option.prefix.name} > ${option.name}` : `${option.name}`"
          >
            <template #option="opt">
              <div class="inline-flex gap-2 flex-row items-center">

                <template v-if="opt.option.prefix">
                  <div class="min-w-4 h-full flex items-center justify-center">
                    <img :src="`assets/bsicons/${opt.option.prefix.editorTypeName || 'bullet'}.png`" />
                  </div>
                  <div style="white-space: nowrap"> {{ opt.option.prefix.name }}</div>
                  <span class="gray">></span>
                </template>
        

                <div class="min-w-4 h-full flex items-center justify-center">
                  <img :src="`assets/bsicons/${opt.option.editorTypeName || 'bullet'}.png`" />
                </div>
                
                <div style="white-space: nowrap"> {{ opt.option.name }} </div>
              </div>
            </template>
          </UtilAutocomplete>
        </td>
      </tr>
      <tr>
        <td>Filter By: </td>
        <td>
          <UtilAutocomplete
            v-model="fields.filterBy"
            :placeholder="`Search Child...`"
            :options="allFilterBy"
            valueField="id"
            filterField="name"
            :default="filterBySelected"
            lazy
          >
            <template #option="opt">
              <div v-if="opt.option" style="white-space: nowrap">
                <template v-if="opt.option.indent >= 1 && !opt.selected">
                  <span v-for="n of opt.option.indent">&nbsp;&nbsp;&nbsp;</span>
                </template>
                <img class="mr-1 align-middle" :src="`assets/bsicons/${opt.option.editorTypeName}.png`" />

                {{ opt.option.name }}
                <span class="gray">{{ getNameExtra(opt.option, false) }}</span>
                <span class="shared" v-if="opt.option.shared"> (shared) </span>
                <span class="gray" v-if="opt.option.rootId === rootId"> (same ancestor)</span>
                <span class="catalogueName" v-if="showCatalogue(opt.option)"> [{{ opt.option.catalogue }}]</span>
              </div>
            </template>
          </UtilAutocomplete>
        </td>
      </tr>
    </table>
    <div>
      <div class="checks">
        <div v-if="canIncludeSelf">
          <input id="includeSelfScope" type="checkbox" v-model="scopeIncludeSelf" />
          <label for="includeSelfScope" class="hastooltip" title="Include the entry carrying this modifier as a candidate for the scope (findParentOrSelf) instead of only its ancestors">Include self</label>
        </div>
        <div>
          <input id="includeSelf" type="checkbox" v-model="fields.self" />
          <label for="includeSelf" v-if="fields.affectsWhat?.startsWith('associations')">Affect Associated Nodes</label>
          <label for="includeSelf" v-else-if="scope === 'self'">Affect Self</label>
          <label for="includeSelf" v-else>Affect Scope</label>
        </div>
        <div>
          <input id="includeChildSelections" type="checkbox" v-model="fields.entries" />
          <label for="includeSelf" v-if="fields.affectsWhat?.startsWith('associations')">	Affect child Selections of Associated Nodes</label>
          <label for="includeChildSelections" v-else>Affect child Selections</label>
        </div>
        <div>
          <input id="includeChildForces" type="checkbox" v-model="fields.group"/>
          <label for="includeChildForces">Affect group associations</label>
        </div>
        <div v-if="!fields.associations" >
          <input id="includeChildForces" type="checkbox" v-model="fields.forces" />
          <label for="includeChildForces">Affect child Forces</label>
        </div>
        <div>
          <input id="recursive" type="checkbox" v-model="fields.recursive" />
          <label for="recursive">Recursive</label>
        </div>
      </div>
    </div>
  </fieldset>
</template>
<script lang="ts">
import PopupDialog from "~/shared_components/PopupDialog.vue";
import type { EditorBase } from "~/assets/shared/battlescribe/bs_main_catalogue";
import type { BSICostType, BSIModifier } from "~/assets/shared/battlescribe/bs_types";
import {
  getParentUnitHierarchy,
  getSearchCategories,
  getSearchElements,
  getParentScopes,
} from "~/assets/ts/catalogue/catalogue_helpers";
import type { EditorSearchItem } from "~/assets/ts/catalogue/catalogue_helpers";
import { filterByItems, getNameExtra } from "~/assets/editor/bs_editor";
import { construct_affects_query, deconstruct_affects_query, Modifier } from "~/assets/shared/battlescribe/bs_main";
import type { AffectsQuery } from "~/assets/shared/battlescribe/bs_main";
import { selfableScopes, splitScopeSelf } from "~/assets/shared/battlescribe/bs_condition";
const scopes = {
  self: { id: undefined, name: "Self" },
  parent: { id: "parent", name: "Parent" },
  roster: { id: "roster", name: "Roster" },
  force: { id: "force", name: "Force" },
  category: { id: "category", name: "Category" },
  ancestor: { id: "ancestor", name: "Ancestor" },
  parents: { id: "ancestor", name: "All Parents" },
  primaryCategory: { id: "primary-category", name: "Primary Category" },
  primaryCatalogue: { id: "primary-catalogue", name: "Primary Catalogue" },
  rootEntry: { id: "root-entry", name: "Root Entry" },
  unit: { id: "unit", name: "Type: Unit" },
  model: { id: "model", name: "Type: Model" },
  upgrade: { id: "upgrade", name: "Type: Upgrade" },
  modelOrUnit: { id: "model-or-unit", name: "Type: Model or Unit" },
  entryNotUpgrade: { id: "non-upgrade-entry", name: "Type: Not Upgrade" },
  group: { id: "group", name: "Type: Group" },
  link: { id: "link", name: "Type: Link" },
} as const;
interface ScopeChoice {
  id: string;
  name: string;
  editorTypeName?: string;
  title?: string;
}

export default defineComponent({
  components: { PopupDialog },
  props: {
    item: { type: Object as PropType<BSIModifier & EditorBase>, required: true },
  },
  data: () => ({
    fields: {
      self: true,
      entries: false,
      forces: false,
      recursive: false,
      group: false,
      filterBy: "any",
      affectsWhat: "entries",
    } as AffectsQuery,
  }),
  methods: {
    getNameExtra,
    showCatalogue(opt: EditorSearchItem): boolean {
      if (!opt.catalogue) {
        return false;
      }
      if (opt.catalogue === this.item.catalogue?.getName()) {
        return false;
      }
      return true;
    },
  },
  computed: {
    scope: {
      get() {
        return this.item.scope ?? "self";
      },
      set(val: string) {
        if (val === "self") delete this.item.scope;
        else this.item.scope = val;
      },
    },
    // The scope autocomplete binds to the BASE scope (without the "-self" suffix), while the
    // "include self" checkbox toggles the suffix — so both read and write stay in sync.
    scopeBase: {
      get(): string | undefined {
        const s = this.item.scope;
        if (s == null) return undefined; // "self" option has an undefined id
        return splitScopeSelf(s).base;
      },
      set(val: string | undefined) {
        const includeSelf = this.item.scope ? splitScopeSelf(this.item.scope).self : false;
        const base = val ?? "self";
        const full = includeSelf && selfableScopes.has(base) ? `${base}-self` : base;
        if (full === "self") delete this.item.scope;
        else this.item.scope = full;
      },
    },
    scopeIncludeSelf: {
      get(): boolean {
        return this.item.scope ? splitScopeSelf(this.item.scope).self : false;
      },
      set(val: boolean) {
        const base = this.item.scope ? splitScopeSelf(this.item.scope).base : "self";
        const full = val && selfableScopes.has(base) ? `${base}-self` : base;
        if (full === "self") delete this.item.scope;
        else this.item.scope = full;
      },
    },
    canIncludeSelf(): boolean {
      const base = this.item.scope ? splitScopeSelf(this.item.scope).base : "self";
      return selfableScopes.has(base);
    },
    catalogue() {
      return this.item.getCatalogue();
    },
    type() {
      return this.item.editorTypeName;
    },
    costTypes() {
      const res: BSICostType[] = [];
      for (const elt of this.catalogue.iterateCostTypes()) {
        res.push(elt);
      }
      return res;
    },
    rootId() {
      let item = this.item as any;
      if (!item?.parent) return;
      while (item?.parent && !item.parent.isCatalogue()) {
        item = item.parent;
      }
      return item.id;
    },
    allSelections(): EditorSearchItem[] {
      return getParentUnitHierarchy(this.item);
    },

    allCategories(): EditorSearchItem[] {
      return getSearchCategories(this.catalogue);
    },

    allForces(): EditorSearchItem[] {
      return getSearchElements(this.catalogue, "forceEntriesIterator");
    },

    allEntries(): EditorSearchItem[] {
      return getSearchElements(this.catalogue, "entriesIterator");
    },

    allParents(): EditorSearchItem[] {
      return getParentScopes(this.item);
    },

    allAffects(): Array<any> {
      const normal = [
        {
          name: "Entries",
          value: "entries",
        },
        ...[...this.catalogue.iterateProfileTypes()].map((type) => ({
          name: `Profiles (${type.name})`,
          value: `profiles.${type.name}`,
          editorTypeName: "profileType",
        })),
        {
          name: "Rules",
          value: "rules",
          editorTypeName: "rule",
        },
      ];
      return [...normal, ...normal.map(elt => ({
        ...elt, 
        value: `associations.${elt.value}`,
        prefix: {
          name: "Associations",
          editorTypeName: "association",
        } 
      }))];
    },
    allScopes(): Array<ScopeChoice | EditorSearchItem> {
      const result = [scopes.self, scopes.parent, scopes.force, scopes.roster, scopes.primaryCatalogue] as Array<
        ScopeChoice | EditorSearchItem
      >;
      if (this.type !== "forceEntry") {
        result.push(scopes.rootEntry, scopes.unit, scopes.model, scopes.upgrade, scopes.modelOrUnit, scopes.entryNotUpgrade, scopes.group, scopes.link);
      }
      result.push(...this.allParents);
      if (this.type !== "forceEntry") {
        result.push(...this.allCategories);
      }
      result.push(...this.allForces);
      return result;
    },
    allFilterBy() {
      const result = [...filterByItems, ...this.allCategories, ...this.allEntries];
      return result;
    },

    filterBySelected() {
      if (!this.fields.filterBy || this.fields.filterBy === "any") {
        return this.allFilterBy[0];
      }

      const base = this.allFilterBy.find((elt) => elt.id === this.fields.filterBy);
      if (base) {
        return base;
      }
      return this.catalogue.findOptionById(this.fields.filterBy) as any as EditorSearchItem;
    },
  },
  watch: {
    // Component instance is reused when clicking between modifiers; re-sync local fields from the new item.
    item: {
      immediate: true,
      handler() {
        this.fields = deconstruct_affects_query(this.item.affects);
      },
    },
    fields: {
      deep: true,
      handler(fields) {
        if (this.fields.associations) {
          this.fields.forces = false
        }
        const built = construct_affects_query(fields);
        // Selecting another modifier re-syncs `fields` from its affects; that is not an edit, so
        // don't write (and normalize) the query back. Only a real change to the fields differs here.
        if (construct_affects_query(deconstruct_affects_query(this.item.affects)) === built) return;
        if (!built || built === "self") {
          delete this.item.affects;
        } else {
          this.item.affects = built;
        }
      },
    },
  },
});
</script>
<style scoped lang="scss">
.checks > div {
  display: inline-block;
  margin-right: 10px;
}
</style>
